const impactPortraitFor=name=>{
  const registered=portraits.people?.[name];
  if(['image','imagined'].includes(registered?.status)&&registered?.file)return {file:registered.file,kind:registered.status==='imagined'?'imagined':'sourced',label:registered.status==='imagined'?'AI想象像':''};
  const imagined=storytelling.people?.[name]?.portrait||'';
  return {file:imagined,kind:imagined?'imagined':'none',label:imagined?'AI想象像':''};
};
const eventImpactHtmlById=Object.fromEntries(impactGraphData.graphs.map(graph=>[
  graph.eventId,
  renderCompactImpactGraph({graph,stageId:graph.compactStageId,portraitFor:impactPortraitFor,personHref:name=>core.some(person=>person.name===name)?`people.html?person=${encodeURIComponent(name)}`:''})
]));
const imaginedPortraitNames = new Set([
  ...Object.entries(portraits.people||{}).filter(([,record])=>record.status==='imagined'&&record.file).map(([name])=>name),
  ...Object.entries(storytelling.people||{}).filter(([name,record])=>record.portrait&&!portraits.people?.[name]?.file).map(([name])=>name)
]);
const imaginedPortraitCount = imaginedPortraitNames.size;
const normalize = s => String(s||'').replaceAll('熾','炽').replaceAll('鎮','镇').replaceAll('鈺','钰').replaceAll('見','见').replaceAll('載','载').replaceAll('鈞','钧').replaceAll('檢','检').replaceAll('權','权').replaceAll('標','标').replaceAll('潤','润').replaceAll('祐','祐').replace(/\s+/g,'');
const childCounts = {};
for (const p of core.filter(x=>x.category==='皇帝')) {
  const key=normalize(p.name);
  const records=allChildren.filter(x=>normalize(x.parent).includes(key));
  childCounts[p.name]={
    total:records.length,
    sons:records.filter(x=>x.sex==='男').length,
    daughters:records.filter(x=>x.sex==='女').length,
    important:children.filter(x=>normalize(x.parent).includes(key)).length,
  };
}
const lifeEraLabels = {};
for (const person of [...core, ...children]) {
  const timeline=peopleTimeline.people?.find(item=>normalize(item.name)===normalize(person.name||person.title));
  const yearLabels=[
    [person.birth,person.death].filter(Boolean).join('—')||'年代待考',
    timeline?.timeline_year_label||'年代待考',
    person.office_start||person.office_end?`${person.office_start||''}—${person.office_end||''}`:(timeline?.timeline_year_label||'活动年代待考'),
    person.death&&person.death!=='待考'?String(person.death):'身后',
  ];
  lifeEraLabels[person.name||person.title]=yearLabels.map(formatLifeEraLabel);
}
const outDir = 'outputs/019fc8d2-0e97-7ed3-a23b-47b434c01dc9';
await fs.mkdir(outDir, {recursive:true});
const emperorNames = new Set(core.filter(person=>person.category==='皇帝').map(person=>normalize(person.name)));
const childSourceRecords = children.map((person)=>({
  ...person,
  name:person.name||person.title||'未命名',
  category:'皇室子女',
  domains:['宫廷内廷'],
  office:person.title||'皇室子女',
  hometown:'待考',
  summary:person.summary||person.notes||'谱系记录。',
  evaluation:person.evaluation||'资料不足，不作综合历史评分。',
  score:person.score??'',
  confidence:person.confidence||'低',
  source1:person.source_url,
  source2:'https://zh.wikisource.org/zh-hans/明史_(四庫全書本)/卷121',
  notes:[person.primary_source,person.notes].filter(Boolean).join('；'),
})).filter(person=>!emperorNames.has(normalize(person.name)));
const buildPeople = [
  ...core,
  ...childSourceRecords,
];
const escapeHtml = value => String(value ?? '').replace(/[&<>'"]/g, char => ({
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  "'": '&#39;',
  '"': '&quot;',
}[char]));
const renderSouthernMingBranch = branch => {
  const sourceLink = sourceId => {
    const source = peopleTimeline.source_catalog?.[sourceId];
    if (!source) return '';
    return `<a href="${escapeHtml(source.url)}" target="_blank" rel="noreferrer">${escapeHtml(source.label)}</a>`;
  };
  const rulers = (branch.primary || []).map(item => {
    const person = core.find(record => normalize(record.name) === normalize(item.name)) || {};
    const sources = (item.sourceIds || []).map(sourceLink).filter(Boolean).join('');
    return `<article class="southern-branch-ruler">
      <a class="southern-branch-profile" href="people.html?person=${encodeURIComponent(item.name)}">
      <span>${escapeHtml(item.era)} · ${escapeHtml(item.start)}—${escapeHtml(item.end)}</span>
      <b>${escapeHtml(item.name)}</b>
      <em>${escapeHtml(person.office || '南明政权人物')}</em>
      <p>${escapeHtml(person.summary || '')}</p>
      </a>
      <small>${sources}</small>
    </article>`;
  }).join('');

  return `<section class="southern-branch" aria-labelledby="southernMingBranchTitle">
    <header class="southern-branch-head">
      <div><span>SOUTHERN MING BRANCH</span><h2 id="southernMingBranchTitle">${escapeHtml(branch.title)} · ${escapeHtml(branch.range)}</h2></div>
      <p>${escapeHtml(branch.boundary)}</p>
    </header>
    <div class="southern-branch-list">${rulers}</div>
    <p class="southern-branch-note">${escapeHtml((branch.notes || []).join(' '))}</p>
  </section>`;
};
