function personAssessmentFactHtml(p){return '<div class="fact person-assessment-fact"><span>人物概览</span><div class="person-assessment-grid"><article class="person-assessment-card"><h5>生平事迹</h5><p>'+esc(p.summary||'—')+'</p></article><article class="person-assessment-card"><h5>历史评价</h5><p>'+esc(p.evaluation||'—')+'</p></article></div></div>'}
function emperorIdentityFactHtml(p){const identity=emperorIdentityMeta(p)||{};const rows=[['身份 / 庙号',(p.category||'皇帝')+' · '+(identity.templeName||'待考'),identity.templeNote||''],['年号',identity.eraName||p.alt||'待考','']];return '<div class="fact founder-identity">'+rows.map(([label,value,note])=>'<div class="founder-identity-row"><span>'+esc(label)+'</span><b'+(note?' title="'+esc(note)+'"':'')+'>'+esc(value)+'</b></div>').join('')+'</div>'}
function emperorDomainFactHtml(p){const identity=emperorIdentityMeta(p);return '<div class="fact founder-domain"><span>历史领域</span>'+domainHtml({domains:identity?.domains||p.domains||[]})+'</div>'}
function emperorTombFactHtml(p){const identity=emperorIdentityMeta(p)||{};return '<div class="fact founder-tomb"><span>陵寝</span><b>'+esc(identity.tomb||'待考')+'</b></div>'}
function emperorGovernanceHtml(profile,p){const reforms=profile?.governance||profile?.basicInfo?.institutionReforms||[];if(!reforms.length)return '';const lead=p.name==='朱元璋'?'朱元璋不仅建立了明朝，也重新安排了中央行政、军事与监察权力。以下变化说明他怎样把更多决策权集中到皇帝手中。':'皇帝名义上关联大量国家机构。这里不罗列机构名称，只说明这位皇帝真正创设、废除、恢复或重组了什么。';return '<section class="founder-governance"><header class="founder-governance-head"><small>GOVERNANCE · 统治结构</small><h4>统治与制度</h4><p>'+esc(lead)+'</p></header><div class="founder-governance-list">'+reforms.map(item=>'<article class="founder-governance-item"><div class="founder-governance-title"><h5>'+esc(item.title)+'</h5><em>'+esc(item.relation)+'</em></div><p>'+esc(item.description)+'</p></article>').join('')+'</div></section>'}
function founderAssessmentFactHtml(assessment){if(!assessment)return '';return '<div class="fact founder-assessment-fact"><span>统治概览</span><div class="founder-assessment-grid"><article class="founder-assessment-card"><h5>'+esc(assessment.achievementsTitle)+'</h5><p>'+esc(assessment.achievements)+'</p></article><article class="founder-assessment-card"><h5>'+esc(assessment.evaluationTitle)+'</h5><p>'+esc(assessment.evaluation)+'</p></article></div></div>'}
function emperorRoyalRelationsData(p,profile){if(profile?.basicInfo?.royalRelations)return profile.basicInfo.royalRelations;const lineage=p.lineage||{};const find=label=>lineage.relations?.find(item=>item.label===label)?.value||'';const father=find('父');const mother=find('母');const predecessor=lineage.relations?.find(item=>/前任/.test(item.label));return {columns:[{title:'家庭出身',lines:[father?'父：'+father:'父系：待考',mother?'母：'+mother:'母系：待考',lineage.branch?'支系：'+lineage.branch:'支系：待考']},{title:'子女',lines:['皇子 '+p.sonsTotal+' · 皇女 '+p.daughtersTotal,'合计 '+p.childrenTotal+' 人','本馆收录 '+p.childrenImportant+' 位重要子嗣']},{title:'帝位与继承',lines:[predecessor?predecessor.label+'：'+predecessor.value:'前任：无明朝前任皇帝','帝位来源：'+(lineage.succession||'待考')]}],boundary:'本馆收录 '+p.childrenImportant+' 位重要子嗣，是当前人物关系网的选取范围，不表示其余子女不重要。'+(lineage.boundary?' '+lineage.boundary:'')};}
