function emperorRoyalRelationsHtml(p,profile){const basic={confidence:p.lineage?.confidence||profile?.basicInfo?.confidence||p.confidence||'未知',royalRelations:emperorRoyalRelationsData(p,profile)};return founderRoyalRelationsHtml(basic)}
function personRecord(name){return allRecords.find(p=>canonical(p.name)===canonical(name))}
function eventRecord(id){return events.find(e=>e.id===id)}
function peopleForEvent(event){if(!event)return [];const seen=new Set();return (event.people||[]).map(name=>all.find(p=>canonical(p.name)===canonical(name))).filter(p=>{if(!p||seen.has(canonical(p.name)))return false;seen.add(canonical(p.name));return true})}
function eventsForPerson(person){if(!person)return [];return events.filter(e=>(e.people||[]).some(name=>canonical(name)===canonical(person.name))).sort((a,b)=>(a.year-b.year)||a.id.localeCompare(b.id))}
function eventPageHref(event){const prefix=document.body.classList.contains('people-page')?'':'明史数字博物馆/';return prefix+'events.html?event='+encodeURIComponent(event.id)}
function relatedEventsHtml(person){const related=eventsForPerson(person);if(!related.length)return '';return '<h4>相关事件</h4><div class="related-events">'+related.map(e=>'<a href="'+esc(eventPageHref(e))+'" data-related-event="'+esc(e.id)+'"><time><strong>'+esc(e.eraYear)+'</strong><span>'+esc(e.date)+'</span></time><b>'+esc(e.title)+'</b><em>'+esc(e.category)+' →</em></a>').join('')+'</div>'}
function syncPeopleQuery(kind,value){if(!document.body.classList.contains('people-page'))return;const url=new URL(location.href);url.searchParams.delete('person');url.searchParams.delete('event');if(kind&&value)url.searchParams.set(kind,value);history.replaceState(null,'',url.href)}
function eventPeopleHtml(e,detail=false){const people=(e.people||[]).map(name=>personRecord(name)?'<button class="personjump" data-person="'+esc(name)+'">'+esc(name)+' ↗</button>':'<span class="plainperson">'+esc(name)+'</span>').join('');const institutions=(e.institutions||[]).map(name=>'<span class="institutiontag">'+esc(name)+'</span>').join('');return '<div class="'+(detail?'event-people-detail':'eventlinks')+'">'+people+institutions+'</div>'}
function eventPeopleCtaHtml(e){const count=peopleForEvent(e).length;if(!count)return '';return '<button class="event-people-cta" data-event-people="'+esc(e.id)+'"><span>查看本事件全部人物</span><small>'+count+' 位本馆人物 →</small></button>'}
function eventImpactGraphHtml(e){return e.impactHtml||''}
let activeDrawerContentKey='';
