document.getElementById('personEvent').innerHTML='<option value="">全部关联事件</option>'+eventStages.map(stage=>'<optgroup label="'+esc(stage.label+' · '+stage.range)+'">'+events.filter(e=>e.stage===stage.id).map(e=>'<option value="'+esc(e.id)+'">'+esc(e.eraYear+' · '+e.date+' · '+e.title+'（本馆 '+peopleForEvent(e).length+' 人）')+'</option>').join('')+'</optgroup>').join('');
document.getElementById('domain').innerHTML='<option value="">全部历史领域</option>'+domains.map(d=>'<option value="'+esc(d)+'">'+esc(d)+'</option>').join('');
