document.getElementById('eventSearch').oninput=e=>{eventState.q=e.target.value;renderEvents()};document.getElementById('eventCategory').onchange=e=>{eventState.category=e.target.value;renderEvents()};document.getElementById('eventReset').onclick=()=>{eventState={stage:'',category:'',q:''};document.getElementById('eventSearch').value='';document.getElementById('eventCategory').value='';renderEvents()};
document.getElementById('search').oninput=e=>{state.q=e.target.value;render()};document.getElementById('personEvent').onchange=e=>{state.event=e.target.value;state.parent='';syncPeopleQuery(state.event?'event':'',state.event);render()};document.getElementById('domain').onchange=e=>{state.domain=e.target.value;render()};document.getElementById('institution').onchange=e=>{state.institution=e.target.value;render()};document.getElementById('confidence').onchange=e=>{state.confidence=e.target.value;render()};document.getElementById('sort').onchange=e=>{state.sort=e.target.value;render()};document.getElementById('reset').onclick=()=>{state={category:'全部',domain:'',institution:'',q:'',parent:'',event:'',confidence:'',sort:'time'};['search','personEvent','domain','institution','confidence'].forEach(id=>document.getElementById(id).value='');document.getElementById('sort').value='time';syncPeopleQuery('',null);render()};document.getElementById('close').onclick=closeDetail;document.getElementById('veil').onclick=closeDetail;document.removeEventListener('keydown',handleDrawerKeydown);document.addEventListener('keydown',handleDrawerKeydown);renderEvents();render();
